#!/usr/bin/env python3
"""Embed src/js/vendor/acorn.js into a C string literal.

The .h is COMMITTED, so the build needs no extra step and a checkout compiles
as-is.  t/comcon_parser_vendor.t re-runs this and diffs, so the committed .h
cannot drift from the .js it claims to embed -- a generated file nobody checks
is a place for a silent edit to hide, and this one is TCB.

    python3 src/js/vendor/gen-acorn-h.py        # regenerate
    python3 src/js/vendor/gen-acorn-h.py --check # exit 1 if the .h is stale
"""
import hashlib, pathlib, sys

HERE = pathlib.Path(__file__).resolve().parent
SRC, OUT = HERE / "acorn.js", HERE / "acorn_js.h"

def render() -> str:
    raw = SRC.read_bytes()
    sha = hashlib.sha256(raw).hexdigest()
    # One C string per source line: readable in a diff, and no line runs past
    # the 4095-char limit C89 guarantees for a single string literal.
    body = []
    for line in raw.split(b"\n"):
        esc = (line.replace(b"\\", b"\\\\").replace(b'"', b'\\"')
                   .replace(b"\r", b"\\r").replace(b"\t", b"\\t"))
        body.append('    "' + esc.decode("utf-8", "backslashreplace") + '\\n"')
    return (
        "/* GENERATED by src/js/vendor/gen-acorn-h.py -- DO NOT EDIT.\n"
        " *\n"
        " * acorn 8.14.0 (MIT), vendored for D5b-2.  Provenance, the TCB rules\n"
        " * it lives under, and how to re-verify: src/js/vendor/PROVENANCE.md\n"
        " *\n"
        " * acorn.js sha256: " + sha + "\n"
        " */\n\n"
        "#ifndef NGX_JS_VENDOR_ACORN_H\n"
        "#define NGX_JS_VENDOR_ACORN_H\n\n"
        '#define NGX_JS_ACORN_SHA256 "' + sha + '"\n\n'
        "static const char  ngx_js_vendor_acorn_js[] =\n"
        + "\n".join(body) + ";\n\n"
        "#endif /* NGX_JS_VENDOR_ACORN_H */\n"
    )

if __name__ == "__main__":
    text = render()
    if "--check" in sys.argv:
        cur = OUT.read_text() if OUT.exists() else ""
        if cur != text:
            print("STALE: acorn_js.h does not match acorn.js -- regenerate", file=sys.stderr)
            sys.exit(1)
        print("acorn_js.h is in sync with acorn.js")
    else:
        OUT.write_text(text)
        print("wrote", OUT, "(%d bytes)" % len(text))
